#include "player.h"
#include "Engine/portal.h"
#include "Engine/state.h"
#include <math.h>
static void collide(const game_player_t*p,const level_data_t*l,camera_t*c){if(!p||!l||!c||!l->sectors)return;for(i32 s=0;s<l->sector_count;++s){const level_sector_data_t*sec=&l->sectors[s];for(i32 q=0;q<sec->quad_count;++q){const level_quad_t*w=&sec->quads[q];if(w->portal_id>0||!w->is_solid||w->is_billboard)continue;f32 ry[16],rx[16],rz[16],m[16],t[16];mat4_rotate_y(ry,-DEG2RAD(w->rot.y));mat4_rotate_x(rx,-DEG2RAD(w->rot.x));mat4_rotate_z(rz,-DEG2RAD(w->rot.z));mat4_multiply(t,rx,ry);mat4_multiply(m,rz,t);const vec3s n={m[8],m[9],m[10]},r={m[0],m[1],m[2]},u={m[4],m[5],m[6]},d=vec3_sub(c->pos,w->pos);const f32 dist=vec3_dot(d,n);if(fabsf(dist)>p->collision_radius)continue;const f32 x=vec3_dot(d,r),y=vec3_dot(d,u),margin=p->collision_radius*.5f;if(x< -margin||x>w->size.x+margin||y< -margin||y>w->size.y+margin)continue;const f32 push=dist>=0?p->collision_radius-dist:-(p->collision_radius+dist);c->pos=vec3_add(c->pos,vec3_scale(n,push));}}}
void game_player_init(game_player_t*p){if(p)*p=(game_player_t){18.5f,4.5f,.5f};}
void game_player_update(game_player_t*p,level_data_t*l){if(!p||!l||state.id!=STATE_PLAYING||!state.cam||!state.win)return;const vec3s previous=state.cam->pos;vec3s forward={state.cam->front.x,0,state.cam->front.z};if(vec3_magnitude(forward)>.0001f)forward=vec3_normalize(forward);const vec3s right=vec3_normalize(vec3_cross(state.cam->front,state.cam->up));vec3s move={0,0,0};if(glfwGetKey(state.win,GLFW_KEY_W)==GLFW_PRESS)move=vec3_add(move,forward);if(glfwGetKey(state.win,GLFW_KEY_S)==GLFW_PRESS)move=vec3_sub(move,forward);if(glfwGetKey(state.win,GLFW_KEY_A)==GLFW_PRESS)move=vec3_sub(move,right);if(glfwGetKey(state.win,GLFW_KEY_D)==GLFW_PRESS)move=vec3_add(move,right);if(vec3_magnitude(move)>.0001f){move=vec3_normalize(move);state.cam->pos=vec3_add(state.cam->pos,vec3_scale(move,p->move_speed*state.dt));(void)portal_try_teleport(l,previous,state.cam);collide(p,l,state.cam);}f32 ground=0;const f32 smooth=1-expf(-2.45f*state.dt);if(level_get_height(l,state.cam->pos,&ground))state.cam->pos.y=lerp(state.cam->pos.y,ground+p->eye_height,smooth);else state.cam->pos=vec3_lerp(state.cam->pos,previous,smooth);}
